ALTER TABLE person ADD COLUMN IF NOT EXISTS employee_code VARCHAR(32) NULL, ADD COLUMN IF NOT EXISTS display_name VARCHAR(255) NULL, ADD COLUMN IF NOT EXISTS position_title VARCHAR(255) NULL, ADD COLUMN IF NOT EXISTS employment_status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', ADD COLUMN IF NOT EXISTS national_id_masked VARCHAR(32) NULL, ADD UNIQUE KEY IF NOT EXISTS person_employee_code_unique (employee_code);
ALTER TABLE organization ADD COLUMN IF NOT EXISTS code VARCHAR(32) NULL, ADD COLUMN IF NOT EXISTS parent_id CHAR(36) NULL, ADD UNIQUE KEY IF NOT EXISTS organization_code_unique (code), ADD CONSTRAINT organization_parent_fk FOREIGN KEY IF NOT EXISTS (parent_id) REFERENCES organization(id);
